import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import { fade } from "@remotion/transitions/fade";
import { BRAND } from "@/lib/brand";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
  compoundReveal,
  inOutEnvelope,
} from "../motion";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = 15;

// ─────────────────────────────────────────────
// Background
// ─────────────────────────────────────────────
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/background.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ─────────────────────────────────────────────
// SCENE 1 — Hero declaration: "No more friction."
// Kinetic, oversized headline with letter-by-letter reveal
// ─────────────────────────────────────────────
const SCENE_ONE_DURATION = 175;

const SceneOne: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  // Eyebrow
  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");
  const eyebrowDrift = ambientDrift(frame, 1.5, 90, "eyebrow-s1");

  // Hero "No more" word
  const noMoreIn = springIn(frame, vfps, 10, "SNAPPY");

  // Hero word "friction." — letter-by-letter
  const frictionWord = "friction.";
  const frictionStart = 22;

  // Subhead
  const subIn = springIn(frame, vfps, 60, "GENTLE");
  const subDrift = ambientDrift(frame, 2, 110, "sub-s1");

  // Caption bottom-right (monospace)
  const captionIn = springIn(frame, vfps, 78, "GENTLE");

  // Background glow
  const glow = interpolate(frame, [0, 30, 140, 175], [0, 0.55, 0.55, 0.42], {
    extrapolateRight: "clamp",
  });

  // Parallax band drift
  const bandDrift = frame * 0.12;

  return (
    <AbsoluteFill
      style={{
        fontFamily: "Inter, sans-serif",
        background: `radial-gradient(120% 90% at 18% 25%, ${COLORS.card}, ${COLORS.bg} 65%)`,
        overflow: "hidden",
      }}
    >
      {/* Soft additive glow behind hero */}
      <div
        style={{
          position: "absolute",
          left: "-8%",
          top: "20%",
          width: "70%",
          height: 520,
          background: COLORS.orange,
          filter: "blur(120px)",
          opacity: glow,
          mixBlendMode: "screen",
          borderRadius: "50%",
        }}
      />

      {/* Bottom dotted band, parallax */}
      <div
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          bottom: 0,
          height: "18%",
          backgroundImage: `radial-gradient(circle, ${COLORS.orange} 1.5px, transparent 2px)`,
          backgroundSize: "28px 28px",
          opacity: 0.18,
          transform: `translateY(${Math.sin(bandDrift / 20) * 4}px)`,
          maskImage: "linear-gradient(to top, black, transparent)",
          WebkitMaskImage: "linear-gradient(to top, black, transparent)",
        }}
      />

      {/* Eyebrow — top left, monospace meta */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          top: `calc(11% + ${eyebrowDrift}px)`,
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [12, 0])}px)`,
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 36,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        01 / the pitch
      </div>

      {/* Hero block — anchored top-left, oversized */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          top: "26%",
          maxWidth: "82%",
        }}
      >
        {/* "No more" — small line, sets the rhythm */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 120,
            fontWeight: 700,
            color: COLORS.textMuted,
            letterSpacing: "-0.04em",
            lineHeight: 0.95,
            opacity: noMoreIn,
            transform: `translateY(${interpolate(noMoreIn, [0, 1], [40, 0])}px) scale(${interpolate(noMoreIn, [0, 1], [0.94, 1])})`,
            filter: `blur(${interpolate(noMoreIn, [0, 1], [8, 0])}px)`,
            marginBottom: 16,
          }}
        >
          No more
        </div>

        {/* "friction." — letter-by-letter SNAPPY reveal, monstrous */}
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 560,
            fontWeight: 900,
            color: COLORS.text,
            letterSpacing: "-0.06em",
            lineHeight: 0.9,
            display: "flex",
            textShadow: `0 8px 80px ${COLORS.orangeTint}`,
          }}
        >
          {frictionWord.split("").map((ch, i) => {
            const letter = springIn(
              frame,
              vfps,
              frictionStart + i * TIMING.staggerLetter,
              "SNAPPY",
            );
            const isPeriod = ch === ".";
            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  opacity: letter,
                  transform: `translateY(${interpolate(letter, [0, 1], [120, 0])}px) scale(${interpolate(letter, [0, 1], [0.85, 1])}) rotate(${interpolate(letter, [0, 1], [-4, 0])}deg)`,
                  filter: `blur(${interpolate(letter, [0, 1], [14, 0])}px)`,
                  color: isPeriod ? COLORS.orange : COLORS.text,
                  transformOrigin: "50% 80%",
                  whiteSpace: "pre",
                }}
              >
                {ch}
              </span>
            );
          })}
        </div>
      </div>

      {/* Subhead — anchored bottom-left, narrow column */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          bottom: `calc(16% + ${subDrift}px)`,
          maxWidth: "44%",
          opacity: subIn,
          transform: `translateY(${interpolate(subIn, [0, 1], [20, 0])}px)`,
          fontFamily: "Inter, sans-serif",
          fontSize: 44,
          fontWeight: 500,
          color: COLORS.textMuted,
          letterSpacing: "-0.01em",
          lineHeight: 1.35,
          borderLeft: `3px solid ${COLORS.orange}`,
          paddingLeft: 28,
        }}
      >
        Three things stand between you and shipping. We just removed them.
      </div>

      {/* Monospace caption bottom-right */}
      <div
        style={{
          position: "absolute",
          right: "7%",
          bottom: "9%",
          opacity: captionIn,
          transform: `translateY(${interpolate(captionIn, [0, 1], [10, 0])}px)`,
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 28,
          color: COLORS.textSubtle,
          letterSpacing: "0.12em",
          textAlign: "right",
        }}
      >
        apify.com / launching now
      </div>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// SCENE 2 — The three "No more" list
// Staggered rows with strike-through orange marks
// ─────────────────────────────────────────────
const SCENE_TWO_DURATION = 360;

type Item = { kill: string; descriptor: string };
const ITEMS: Item[] = [
  { kill: "API Keys", descriptor: "Auth is handled. Forget rotating tokens." },
  { kill: "credit cards", descriptor: "Start free. No card upfront, ever." },
  { kill: "billing", descriptor: "Pay only for what you actually run." },
];

const ItemRow: React.FC<{ item: Item; index: number }> = ({ item, index }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Row reveal — LIQUID for premium settle
  const rowIn = staggeredSpring(
    frame,
    vfps,
    index,
    40,
    TIMING.staggerLong,
    "LIQUID",
  );

  // Strikethrough line draw — orange, after row lands
  const strikeStart = 40 + index * TIMING.staggerLong + 14;
  const strikeProgress = springIn(frame, vfps, strikeStart, "LIQUID");

  // Descriptor — eases in last
  const descIn = springIn(
    frame,
    vfps,
    40 + index * TIMING.staggerLong + 20,
    "GENTLE",
  );

  // Ambient breath
  const rowDrift = ambientDrift(frame, 1.5, 100 + index * 17, `row-${index}`);

  return (
    <div
      style={{
        display: "flex",
        alignItems: "flex-start",
        gap: 56,
        opacity: rowIn,
        transform: `translateX(${interpolate(rowIn, [0, 1], [-60, 0])}px) translateY(${rowDrift}px)`,
        filter: `blur(${interpolate(rowIn, [0, 1], [6, 0])}px)`,
      }}
    >
      {/* Index numeral */}
      <div
        style={{
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 44,
          color: COLORS.orange,
          fontWeight: 600,
          letterSpacing: "0.05em",
          width: 110,
          paddingTop: 28,
          flexShrink: 0,
        }}
      >
        0{index + 1}
      </div>

      {/* Text column */}
      <div style={{ flex: 1, paddingTop: 8 }}>
        {/* Killed phrase: "No more <X>" with strike */}
        <div
          style={{
            display: "flex",
            alignItems: "baseline",
            gap: 30,
            flexWrap: "wrap",
            fontFamily: "Inter, sans-serif",
            fontSize: 144,
            fontWeight: 800,
            color: COLORS.text,
            letterSpacing: "-0.04em",
            lineHeight: 1,
          }}
        >
          <span
            style={{
              color: COLORS.textSubtle,
              fontWeight: 600,
              fontSize: 96,
            }}
          >
            No more
          </span>
          <span
            style={{
              position: "relative",
              display: "inline-block",
              color: COLORS.text,
            }}
          >
            {item.kill}
            {/* Orange strike-through line, draws L→R */}
            <div
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: "55%",
                height: 12,
                background: COLORS.orange,
                borderRadius: 6,
                transformOrigin: "left center",
                transform: `scaleX(${strikeProgress})`,
                boxShadow: `0 0 24px ${COLORS.orange}`,
              }}
            />
          </span>
        </div>

        {/* Descriptor */}
        <div
          style={{
            marginTop: 28,
            fontFamily: "Inter, sans-serif",
            fontSize: 38,
            fontWeight: 500,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.35,
            opacity: descIn,
            transform: `translateY(${interpolate(descIn, [0, 1], [12, 0])}px)`,
            maxWidth: "78%",
          }}
        >
          {item.descriptor}
        </div>
      </div>
    </div>
  );
};

const SceneTwo: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();

  // Eyebrow header
  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");

  // Section headline
  const headlineIn = springIn(frame, vfps, 12, "SNAPPY");
  const highlightIn = springIn(frame, vfps, 22, "LIQUID");

  // Wedge in bottom-right corner (rising stars motif)
  const wedgeIn = springIn(frame, vfps, 30, "LIQUID");
  const wedgeDrift = ambientDrift(frame, 3, 140, "wedge");

  return (
    <AbsoluteFill
      style={{
        fontFamily: "Inter, sans-serif",
        background: `radial-gradient(140% 100% at 100% 0%, ${COLORS.card} 0%, ${COLORS.bg} 60%)`,
        overflow: "hidden",
      }}
    >
      {/* Decorative wedge bottom-right */}
      <div
        style={{
          position: "absolute",
          right: 0,
          bottom: 0,
          width: 0,
          height: 0,
          borderRight: `1100px solid ${COLORS.orangeDeep}`,
          borderTop: "700px solid transparent",
          opacity: 0.14 * wedgeIn,
          transform: `translate(${wedgeDrift}px, ${wedgeDrift * 0.5}px)`,
          filter: "blur(2px)",
        }}
      />

      {/* Top eyebrow */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          top: "9%",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 32,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        what we removed
      </div>

      {/* Section headline */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          top: "14%",
          maxWidth: "78%",
          fontFamily: "Inter, sans-serif",
          fontSize: 112,
          fontWeight: 700,
          color: COLORS.text,
          letterSpacing: "-0.035em",
          lineHeight: 1.02,
          opacity: headlineIn,
          transform: `translateY(${interpolate(headlineIn, [0, 1], [28, 0])}px)`,
        }}
      >
        Three blockers,{" "}
        <span
          style={{
            background: COLORS.orangeTint,
            borderBottom: `4px solid ${COLORS.orange}`,
            padding: "0 14px",
            borderRadius: 8,
            clipPath: `inset(0 ${interpolate(highlightIn, [0, 1], [100, 0])}% 0 0)`,
            color: COLORS.text,
          }}
        >
          gone
        </span>
        .
      </div>

      {/* List */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          right: "7%",
          top: "34%",
          display: "flex",
          flexDirection: "column",
          gap: 72,
        }}
      >
        {ITEMS.map((item, i) => (
          <ItemRow key={i} item={item} index={i} />
        ))}
      </div>

      {/* Bottom footer rule */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          right: "7%",
          bottom: "6%",
          display: "flex",
          justifyContent: "space-between",
          alignItems: "center",
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 24,
          color: COLORS.textSubtle,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          opacity: springIn(frame, vfps, 220, "GENTLE"),
        }}
      >
        <span>apify / what we removed</span>
        <span>02 / 03</span>
      </div>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// SCENE 3 — Resolution: "Just ship." + CTA
// Asymmetric layout, outlined pill CTA
// ─────────────────────────────────────────────
const SCENE_THREE_DURATION = 200;

const SceneThree: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Eyebrow
  const eyebrowIn = springIn(frame, vfps, 4, "GENTLE");

  // "Just" small word
  const justIn = springIn(frame, vfps, 10, "SNAPPY");

  // "ship." — hero
  const shipWord = "ship.";
  const shipStart = 22;

  // Subhead
  const subIn = springIn(frame, vfps, 60, "GENTLE");

  // CTA pill
  const ctaIn = springIn(frame, vfps, 78, "LIQUID");
  const ctaBreath = ambientDrift(frame, 1.5, 70, "cta");

  // Meta line
  const metaIn = springIn(frame, vfps, 96, "GENTLE");

  // Glow
  const glow = interpolate(frame, [60, 100, 200], [0, 0.5, 0.45], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        fontFamily: "Inter, sans-serif",
        background: `radial-gradient(120% 90% at 80% 40%, ${COLORS.card}, ${COLORS.bg} 60%)`,
        overflow: "hidden",
      }}
    >
      {/* Orange glow behind ship */}
      <div
        style={{
          position: "absolute",
          left: "20%",
          top: "30%",
          width: "70%",
          height: 600,
          background: COLORS.orange,
          filter: "blur(140px)",
          opacity: glow,
          mixBlendMode: "screen",
          borderRadius: "50%",
        }}
      />

      {/* Eyebrow top-left */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          top: "11%",
          opacity: eyebrowIn,
          transform: `translateY(${interpolate(eyebrowIn, [0, 1], [10, 0])}px)`,
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 32,
          color: COLORS.textSubtle,
          letterSpacing: "0.22em",
          textTransform: "uppercase",
        }}
      >
        03 / so —
      </div>

      {/* Hero block */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          top: "24%",
        }}
      >
        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 112,
            fontWeight: 700,
            color: COLORS.textMuted,
            letterSpacing: "-0.04em",
            lineHeight: 0.95,
            opacity: justIn,
            transform: `translateY(${interpolate(justIn, [0, 1], [40, 0])}px)`,
            filter: `blur(${interpolate(justIn, [0, 1], [8, 0])}px)`,
            marginBottom: 12,
          }}
        >
          Just
        </div>

        <div
          style={{
            fontFamily: "Inter, sans-serif",
            fontSize: 620,
            fontWeight: 900,
            color: COLORS.text,
            letterSpacing: "-0.06em",
            lineHeight: 0.88,
            display: "flex",
            textShadow: `0 8px 100px ${COLORS.orangeTint}`,
          }}
        >
          {shipWord.split("").map((ch, i) => {
            const letter = springIn(
              frame,
              vfps,
              shipStart + i * TIMING.staggerLetter,
              "SNAPPY",
            );
            const isPeriod = ch === ".";
            return (
              <span
                key={i}
                style={{
                  display: "inline-block",
                  opacity: letter,
                  transform: `translateY(${interpolate(letter, [0, 1], [140, 0])}px) scale(${interpolate(letter, [0, 1], [0.82, 1])}) rotate(${interpolate(letter, [0, 1], [-3, 0])}deg)`,
                  filter: `blur(${interpolate(letter, [0, 1], [16, 0])}px)`,
                  color: isPeriod ? COLORS.orange : COLORS.text,
                  transformOrigin: "50% 80%",
                  whiteSpace: "pre",
                }}
              >
                {ch}
              </span>
            );
          })}
        </div>
      </div>

      {/* Right column — subhead + CTA */}
      <div
        style={{
          position: "absolute",
          right: "7%",
          bottom: "14%",
          maxWidth: "40%",
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-end",
          gap: 36,
        }}
      >
        {/* Subhead */}
        <div
          style={{
            opacity: subIn,
            transform: `translateY(${interpolate(subIn, [0, 1], [18, 0])}px)`,
            fontFamily: "Inter, sans-serif",
            fontSize: 40,
            fontWeight: 500,
            color: COLORS.textMuted,
            letterSpacing: "-0.005em",
            lineHeight: 1.35,
            textAlign: "right",
          }}
        >
          Sign in. Pick an Actor.
          <br />
          Run it in 10 seconds.
        </div>

        {/* Outlined orange pill CTA */}
        <div
          style={{
            opacity: ctaIn,
            transform: `translateY(${interpolate(ctaIn, [0, 1], [16, ctaBreath])}px) scale(${interpolate(ctaIn, [0, 1], [0.92, 1])})`,
            border: `2px solid ${COLORS.orange}`,
            borderRadius: 999,
            padding: "26px 56px",
            fontFamily: "Inter, sans-serif",
            fontSize: 38,
            fontWeight: 600,
            color: COLORS.orange,
            letterSpacing: "-0.005em",
            background: "transparent",
            boxShadow: `0 0 60px ${COLORS.orangeTint}`,
          }}
        >
          Try Apify for free →
        </div>

        {/* Meta */}
        <div
          style={{
            opacity: metaIn,
            transform: `translateY(${interpolate(metaIn, [0, 1], [10, 0])}px)`,
            fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
            fontSize: 24,
            color: COLORS.textSubtle,
            letterSpacing: "0.15em",
            textTransform: "uppercase",
            textAlign: "right",
          }}
        >
          apify.com / no card required
        </div>
      </div>

      {/* Bottom-left footer */}
      <div
        style={{
          position: "absolute",
          left: "7%",
          bottom: "6%",
          fontFamily: "ui-monospace, 'SF Mono', Menlo, monospace",
          fontSize: 24,
          color: COLORS.textSubtle,
          letterSpacing: "0.18em",
          textTransform: "uppercase",
          opacity: metaIn,
        }}
      >
        03 / 03
      </div>
    </AbsoluteFill>
  );
};

// ─────────────────────────────────────────────
// Main composition
// ─────────────────────────────────────────────
export const durationInFrames =
  SCENE_ONE_DURATION +
  SCENE_TWO_DURATION +
  SCENE_THREE_DURATION +
  TRANSITION; // 2 transitions × TRANSITION subtracted via overlap

const MainComposition: React.FC = () => {
  return (
    <TransitionSeries>
      <TransitionSeries.Sequence durationInFrames={SCENE_ONE_DURATION + TRANSITION}>
        <SceneOne />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_TWO_DURATION + TRANSITION}>
        <SceneTwo />
      </TransitionSeries.Sequence>
      <TransitionSeries.Transition
        presentation={fade()}
        timing={linearTiming({ durationInFrames: TRANSITION })}
      />

      <TransitionSeries.Sequence durationInFrames={SCENE_THREE_DURATION}>
        <SceneThree />
      </TransitionSeries.Sequence>
    </TransitionSeries>
  );
};

export default MainComposition;
